&lt;h1 class=&quot;separator&quot;&gt;Affichage par source&lt;a class=&quot;headeranchor&quot; id=&quot;Affichage_par_source_7&quot; href=&quot;#Affichage_par_source_7&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h1&gt;&lt;script src=&quot;https://ajax.googleapis.com/ajax/libs/jquery/3.5.1/jquery.min.js&quot;&gt;&lt;/script&gt;
&lt;script&gt;
$(document).on(&#39;change&#39;, &#39;select, input&#39;, &#39;keyup&#39;, function() {
  if ($(&#39;#APG&#39;).is(&#39;:checked&#39;)) {
    $(&#39;.APG&#39;).show();
  } else {
    $(&#39;.APG&#39;).hide();
  }
  if ($(&#39;#ACG&#39;).is(&#39;:checked&#39;)) {
    $(&#39;.ACG&#39;).show();
  } else {
    $(&#39;.ACG&#39;).hide();
  }
  if ($(&#39;#UI&#39;).is(&#39;:checked&#39;)) {
    $(&#39;.UI&#39;).show();
  } else {
    $(&#39;.UI&#39;).hide();
  }
});
&lt;/script&gt;&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Afficher les sources :&lt;/b&gt;
&lt;ul&gt;&lt;li&gt;&lt;input id=&quot;APG&quot; type=&quot;checkbox&quot; checked&gt;&lt;label for=&quot;APG&quot; style=&quot;font-size:14px&quot;&gt;Manuel des joueurs - R&#232;gles avanc&#233;es&lt;/label&gt;&lt;/li&gt;&lt;li&gt;&lt;input id=&quot;ACG&quot; type=&quot;checkbox&quot; checked&gt;&lt;label for=&quot;ACG&quot; style=&quot;font-size:14px&quot;&gt;Manuel des joueurs - Classes avanc&#233;es&lt;/label&gt;&lt;/li&gt;&lt;li&gt;&lt;input id=&quot;UI&quot; type=&quot;checkbox&quot; checked&gt;&lt;label for=&quot;UI&quot; style=&quot;font-size:14px&quot;&gt;L&#39;Art de l&#39;intrigue&lt;/label&gt;&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;&#201;vocation&lt;a class=&quot;headeranchor&quot; id=&quot;&#201;vocation_0&quot; href=&quot;#&#201;vocation_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cri-Per&#231;ant.html&quot; title=&quot;Cri per&#231;ant&quot;&gt;Cri per&#231;ant&lt;/a&gt;&lt;/i&gt;&lt;/b&gt; &lt;i&gt;(AM)&lt;/i&gt;. Inflige des d&#233;g&#226;ts sonores et h&#233;b&#232;te la cible.&lt;/li&gt;
&lt;li&gt;&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;charge-&#201;lectrique.html&quot; title=&quot;D&#233;charge &#233;lectrique&quot;&gt;D&#233;charge &#233;lectrique&lt;/a&gt; (Y)&lt;/i&gt;&lt;/b&gt;. 1d6 points de d&#233;g&#226;ts d&#39;&#233;lectricit&#233;/niveau (max. 5d6).&lt;/li&gt;
&lt;li&gt;&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Disque-Flottant.html&quot; title=&quot;Disque flottant&quot;&gt;Disque flottant&lt;/a&gt; (Y)&lt;/i&gt;&lt;/b&gt;. Disque horizontal de 90 cm de diam&#232;tre portant 50 kg/niveau.&lt;/li&gt;
&lt;span class=&quot;APG&quot;&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Grandes-Illuminations.html&quot; title=&quot;Grandes illuminations&quot;&gt;Grandes illuminations&lt;/a&gt;&lt;/i&gt;&lt;/b&gt; &lt;i&gt;(MJRA)&lt;/i&gt;. Comme &lt;i&gt;illumination&lt;/i&gt; mais touche toutes les cr&#233;atures dans un rayon de 3 m.&lt;/li&gt;&lt;/span&gt;
&lt;li&gt;&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Halo-Ind&#233;sirable.html&quot; title=&quot;Halo ind&#233;sirable&quot;&gt;Halo ind&#233;sirable&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Sarenra&#233;-(Technique).html&quot; title=&quot;Sarenra&#233;&quot;&gt;Sarenra&#233;&lt;/a&gt;)&lt;/i&gt;&lt;/b&gt; &lt;i&gt;(ISG)&lt;/i&gt;. Manifeste un halo autour d&#39;une cible, l&#39;emp&#234;chant de se cacher dans l&#39;obscurit&#233;.&lt;/li&gt;
&lt;li&gt;&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mains-Br&#251;lantes.html&quot; title=&quot;Mains br&#251;lantes&quot;&gt;Mains br&#251;lantes&lt;/a&gt; (Y)&lt;/i&gt;&lt;/b&gt;. 1d4 points de d&#233;g&#226;ts de feu/niveau (max. 5d4).&lt;/li&gt;
&lt;span class=&quot;ACG&quot;&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Petite-Brise.html&quot; title=&quot;Petite brise&quot;&gt;Petite brise&lt;/a&gt;&lt;/i&gt;&lt;/b&gt; &lt;i&gt;(MCA)&lt;/i&gt;. Vent l&#233;ger qui prot&#232;ge une cible des nuages, des gaz, de la chaleur et des vapeurs.&lt;/li&gt;&lt;/span&gt;
&lt;span class=&quot;APG&quot;&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouss&#233;e-Hydraulique.html&quot; title=&quot;Pouss&#233;e hydraulique&quot;&gt;Pouss&#233;e hydraulique&lt;/a&gt; (Y)&lt;/i&gt;&lt;/b&gt; &lt;i&gt;(MJRA)&lt;/i&gt;. Vague d’eau qui bouscule un ennemi.&lt;/li&gt;&lt;/span&gt;
&lt;li&gt;&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Projectile-Magique.html&quot; title=&quot;Projectile magique&quot;&gt;Projectile magique&lt;/a&gt; (Y)&lt;/i&gt;&lt;/b&gt;. 1d4+1 points de d&#233;g&#226;ts, +1 projectile tous les 2 niveaux au-del&#224; de 1 (max. 5).&lt;/li&gt;
&lt;span class=&quot;ACG&quot;&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sabot-Du-Tonnerre.html&quot; title=&quot;Sabot du tonnerre&quot;&gt;Sabot du tonnerre&lt;/a&gt;&lt;/i&gt;&lt;/b&gt; &lt;i&gt;(MCA)&lt;/i&gt;. Fait un croc-en-jambe &#224; une cr&#233;ature &#224; port&#233;e.&lt;/li&gt;&lt;/span&gt;
&lt;li&gt;&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Toucher-De-Combustion.html&quot; title=&quot;Toucher de combustion&quot;&gt;Toucher de combustion&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Ifrit-(Race).html&quot; title=&quot;Les ifrits&quot;&gt;Ifrit&lt;/a&gt;)&lt;/i&gt;&lt;/b&gt; &lt;i&gt;(MR)&lt;/i&gt;. Le personnage porte une attaque qui inflige 1d6 points de d&#233;g&#226;ts et qui risque d&#39;enflammer son adversaire.&lt;/li&gt;
&lt;/ul&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Style de combat (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Style_de_combat_Ext_1&quot; href=&quot;#Style_de_combat_Ext_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 2, un r&#244;deur choisit de se sp&#233;cialiser dans un des styles de combat suivants. Cette sp&#233;cialisation se traduit par des dons suppl&#233;mentaires gagn&#233;s aux niveaux 2, 6, 10, 14 et 18. Le r&#244;deur choisit ces dons suppl&#233;mentaires dans la liste appropri&#233;e. Il peut s&#233;lectionner un don m&#234;me s’il ne remplit pas les conditions qui lui sont associ&#233;es.&lt;br /&gt;&lt;br /&gt;Si le r&#244;deur choisit le style de combat &lt;b&gt;&lt;i&gt;&#224; distance&lt;/i&gt;&lt;/b&gt;, il peut choisir un des dons suivants chaque fois qu’il gagne un don de style de combat : &lt;a class=&quot;pagelink&quot; href=&quot;Tir-Avec-Concentration.html&quot; title=&quot;Tir avec concentration&quot;&gt;Tir avec concentration&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Tir-&#192;-Bout-Portant.html&quot; title=&quot;Tir &#224; bout portant&quot;&gt;Tir &#224; bout portant&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Tir-De-Loin.html&quot; title=&quot;Tir de loin&quot;&gt;Tir de loin&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Tir-De-Pr&#233;cision.html&quot; title=&quot;Tir de pr&#233;cision&quot;&gt;Tir de pr&#233;cision&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Tir-Rapide.html&quot; title=&quot;Tir rapide&quot;&gt;Tir rapide&lt;/a&gt;. Au niveau 6, les dons &lt;a class=&quot;pagelink&quot; href=&quot;Feu-Nourri.html&quot; title=&quot;Feu nourri&quot;&gt;Feu nourri&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;trise-Des-Arbal&#232;tes.html&quot; title=&quot;Ma&#238;trise des arbal&#232;tes&quot;&gt;Ma&#238;trise des arbal&#232;tes&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;trise-Du-Tir-&#192;-Bout-Portant.html&quot; title=&quot;Ma&#238;trise du tir &#224; bout portant&quot;&gt;Ma&#238;trise du tir &#224; bout portant&lt;/a&gt;  et &lt;a class=&quot;pagelink&quot; href=&quot;Science-Du-Tir-De-Pr&#233;cision.html&quot; title=&quot;Science du tir de pr&#233;cision&quot;&gt;Science du tir de pr&#233;cision&lt;/a&gt; s’ajoutent &#224; la liste. Au niveau 10, les dons &lt;a class=&quot;pagelink&quot; href=&quot;Tir-En-Mouvement.html&quot; title=&quot;Tir en mouvement&quot;&gt;Tir en mouvement&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Viser-Juste.html&quot; title=&quot;Viser juste&quot;&gt;Viser juste&lt;/a&gt; s’ajoutent &#224; la liste.&lt;br /&gt;&lt;br /&gt;Si le r&#244;deur choisit le style de combat &lt;b&gt;&lt;i&gt;&#224; deux armes&lt;/i&gt;&lt;/b&gt;, il peut choisir un des dons suivants chaque fois qu’il gagne un don de style de combat : &lt;a class=&quot;pagelink&quot; href=&quot;Arme-En-Main.html&quot; title=&quot;Arme en main&quot;&gt;Arme en main&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Combat-&#192;-Deux-Armes.html&quot; title=&quot;Combat &#224; deux armes&quot;&gt;Combat &#224; deux armes&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Double-Frappe.html&quot; title=&quot;Double frappe&quot;&gt;Double frappe&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Science-Du-Coup-De-Bouclier.html&quot; title=&quot;Science du coup de bouclier&quot;&gt;Science du coup de bouclier&lt;/a&gt;. Au niveau 6, les dons &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;fense-&#192;-Deux-Armes.html&quot; title=&quot;D&#233;fense &#224; deux armes&quot;&gt;D&#233;fense &#224; deux armes&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Science-Du-Combat-&#192;-Deux-Armes.html&quot; title=&quot;Science du combat &#224; deux armes&quot;&gt;Science du combat &#224; deux armes&lt;/a&gt; s’ajoutent &#224; la liste. Au niveau 10, les dons &lt;a class=&quot;pagelink&quot; href=&quot;&#201;ventration-&#192;-Deux-Armes.html&quot; title=&quot;&#201;ventration &#224; deux armes&quot;&gt;&#201;ventration &#224; deux armes&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Combat-&#192;-Deux-Armes-Sup&#233;rieur.html&quot; title=&quot;Combat &#224; deux armes sup&#233;rieur&quot;&gt;Combat &#224; deux armes sup&#233;rieur&lt;/a&gt; viennent s’ajouter &#224; la liste.&lt;/span&gt;&lt;span class=&quot;APG&quot;&gt;&lt;br /&gt;&lt;br /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - R&#232;gles avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Player&#39;s Guide/Manuel des joueurs - R&#232;gles avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAPG.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt; Si le r&#244;deur choisit le style de combat &lt;b&gt;&lt;i&gt;arbal&#232;te&lt;/i&gt;&lt;/b&gt;, il peut choisir un des dons suivants chaque fois qu’il gagne un don de style de combat : &lt;a class=&quot;pagelink&quot; href=&quot;Rechargement-Rapide.html&quot; title=&quot;Rechargement rapide&quot;&gt;Rechargement rapide&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Tir-Avec-Concentration.html&quot; title=&quot;Tir avec concentration&quot;&gt;Tir avec concentration&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Tir-De-Pr&#233;cision.html&quot; title=&quot;Tir de pr&#233;cision&quot;&gt;Tir de pr&#233;cision&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Viser.html&quot; title=&quot;Viser&quot;&gt;Viser&lt;/a&gt;. Au niveau 6, les dons &lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;trise-Des-Arbal&#232;tes.html&quot; title=&quot;Ma&#238;trise des arbal&#232;tes&quot;&gt;Ma&#238;trise des arbal&#232;tes&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Science-Du-Tir-De-Pr&#233;cision.html&quot; title=&quot;Science du tir de pr&#233;cision&quot;&gt;Science du tir de pr&#233;cision&lt;/a&gt; s&#39;ajoutent &#224; la liste. Au niveau 10, les dons &lt;a class=&quot;pagelink&quot; href=&quot;Tir-En-Mouvement.html&quot; title=&quot;Tir en mouvement&quot;&gt;Tir en mouvement&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Viser-Juste.html&quot; title=&quot;Viser juste&quot;&gt;Viser juste&lt;/a&gt; viennent s&#39;ajouter &#224; la liste.&lt;/span&gt;&lt;span class=&quot;APG&quot;&gt;&lt;br /&gt;&lt;br /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - R&#232;gles avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Player&#39;s Guide/Manuel des joueurs - R&#232;gles avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAPG.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;Si le r&#244;deur choisit le style de combat &lt;b&gt;&lt;i&gt;arme &#224; deux mains&lt;/i&gt;&lt;/b&gt;, il peut choisir un des dons suivants chaque fois qu’il gagne un don de style de combat : &lt;a class=&quot;pagelink&quot; href=&quot;Assaut-Repoussant.html&quot; title=&quot;Assaut repoussant&quot;&gt;Assaut repoussant&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Attaque-En-Puissance.html&quot; title=&quot;Attaque en puissance&quot;&gt;Attaque en puissance&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Coups-Protecteurs.html&quot; title=&quot;Coups protecteurs&quot;&gt;Coups protecteurs&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Encha&#238;nement.html&quot; title=&quot;Encha&#238;nement&quot;&gt;Encha&#238;nement&lt;/a&gt;. Au niveau 6, les dons &lt;a class=&quot;pagelink&quot; href=&quot;Concentration-Malgr&#233;-La-Fureur.html&quot; title=&quot;Concentration malgr&#233; la fureur&quot;&gt;Concentration malgr&#233; la fureur&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Succession-Dencha&#238;nements.html&quot; title=&quot;Succession d&amp;#39;encha&#238;nements&quot;&gt;Succession d’encha&#238;nements&lt;/a&gt; s&#39;ajoutent &#224; la liste. Au niveau 10, les dons &lt;a class=&quot;pagelink&quot; href=&quot;Carnage-Effroyable.html&quot; title=&quot;Carnage effroyable&quot;&gt;Carnage effroyable&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Science-De-La-Destruction.html&quot; title=&quot;Science de la destruction&quot;&gt;Science de la destruction&lt;/a&gt; viennent s&#39;ajouter &#224; la liste.&lt;/span&gt;&lt;span class=&quot;ACG&quot;&gt;&lt;br /&gt;&lt;br /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - Classes avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Class Guide/Manuel des joueurs - Classes avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMCA.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;Si le r&#244;deur choisit le style de combat &lt;b&gt;&lt;i&gt;arme de jet&lt;/i&gt;&lt;/b&gt;, il peut choisir les dons de la liste suivante &#224; chaque fois qu’il gagne un don de style de combat : &lt;a class=&quot;pagelink&quot; href=&quot;Arme-En-Main.html&quot; title=&quot;Arme en main&quot;&gt;Arme en main&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Combat-&#192;-Deux-Armes.html&quot; title=&quot;Combat &#224; deux armes&quot;&gt;Combat &#224; deux armes&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Lanceur-&#192;-Distance.html&quot; title=&quot;Lanceur &#224; distance&quot;&gt;Lanceur &#224; distance&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Tir-De-Pr&#233;cision.html&quot; title=&quot;Tir de pr&#233;cision&quot;&gt;Tir de pr&#233;cision&lt;/a&gt;. Au niveau 6, il ajoute &lt;a class=&quot;pagelink&quot; href=&quot;Lanceur-&#192;-Courte-Distance.html&quot; title=&quot;Lanceur &#224; courte distance&quot;&gt;Lanceur &#224; courte distance&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Fausse-Ouverture.html&quot; title=&quot;Fausse ouverture&quot;&gt;Fausse ouverture&lt;/a&gt; &#224; la liste. Au niveau 10, il ajoute &lt;a class=&quot;pagelink&quot; href=&quot;Viser-Juste.html&quot; title=&quot;Viser juste&quot;&gt;Viser juste&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Tir-En-Mouvement.html&quot; title=&quot;Tir en mouvement&quot;&gt;Tir en mouvement&lt;/a&gt; &#224; la liste.&lt;/span&gt;&lt;span class=&quot;APG&quot;&gt;&lt;br /&gt;&lt;br /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - R&#232;gles avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Player&#39;s Guide/Manuel des joueurs - R&#232;gles avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAPG.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;Si le r&#244;deur choisit le style de combat &lt;b&gt;&lt;i&gt;arme et bouclier&lt;/i&gt;&lt;/b&gt;, il peut choisir un des dons suivants chaque fois qu’il gagne un don de style de combat : &lt;a class=&quot;pagelink&quot; href=&quot;Art-Du-Bouclier.html&quot; title=&quot;Art du bouclier&quot;&gt;Art du bouclier&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Frappe-Du-Bouclier.html&quot; title=&quot;Frappe du bouclier&quot;&gt;Frappe du bouclier&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Combat-&#192;-Deux-Armes.html&quot; title=&quot;Combat &#224; deux armes&quot;&gt;Combat &#224; deux armes&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Science-Du-Coup-De-Bouclier.html&quot; title=&quot;Science du coup de bouclier&quot;&gt;Science du coup de bouclier&lt;/a&gt;. Au niveau 6, les dons &lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-Salvateur.html&quot; title=&quot;Bouclier salvateur&quot;&gt;Bouclier salvateur&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;trise-Du-Bouclier.html&quot; title=&quot;Ma&#238;trise du bouclier&quot;&gt;Ma&#238;trise du bouclier&lt;/a&gt; s&#39;ajoutent &#224; la liste. Au niveau 10, les dons &lt;a class=&quot;pagelink&quot; href=&quot;Art-Du-Bouclier-Sup&#233;rieur.html&quot; title=&quot;Art du bouclier sup&#233;rieur&quot;&gt;Art du bouclier sup&#233;rieur&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Coup-De-Bouclier-Opportuniste.html&quot; title=&quot;Coup de bouclier opportuniste&quot;&gt;Coup de bouclier opportuniste&lt;/a&gt; viennent s&#39;ajouter &#224; la liste.&lt;/span&gt;&lt;span class=&quot;APG&quot;&gt;&lt;br /&gt;&lt;br /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - R&#232;gles avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Player&#39;s Guide/Manuel des joueurs - R&#232;gles avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAPG.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;Si le r&#244;deur choisit le style de combat &lt;b&gt;&lt;i&gt;arme naturelle&lt;/i&gt;&lt;/b&gt;, il peut choisir un des dons suivants chaque fois qu’il gagne un don de style de combat : &lt;a class=&quot;pagelink&quot; href=&quot;Arme-De-Pr&#233;dilection.html&quot; title=&quot;Arme de pr&#233;dilection&quot;&gt;Arme de pr&#233;dilection&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Arme-Naturelle-Sup&#233;rieure.html&quot; title=&quot;Arme naturelle sup&#233;rieure&quot;&gt;Arme naturelle sup&#233;rieure&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Aspect-Bestial.html&quot; title=&quot;Aspect bestial&quot;&gt;Aspect bestial&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Griffes-Coupantes.html&quot; title=&quot;Griffes coupantes&quot;&gt;Griffes coupantes&lt;/a&gt;. Au niveau 6, les dons &lt;a class=&quot;pagelink&quot; href=&quot;Frappe-D&#233;cisive.html&quot; title=&quot;Frappe d&#233;cisive&quot;&gt;Frappe d&#233;cisive&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Griffes-Magiques.html&quot; title=&quot;Griffes magiques&quot;&gt;Griffes magiques&lt;/a&gt; s&#39;ajoutent &#224; la liste. Au niveau 10, les dons &lt;a class=&quot;pagelink&quot; href=&quot;Attaques-Multiples.html&quot; title=&quot;Attaques multiples&quot;&gt;Attaques multiples&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Science-De-La-Frappe-D&#233;cisive.html&quot; title=&quot;Science de la frappe d&#233;cisive&quot;&gt;Science de la frappe d&#233;cisive&lt;/a&gt; viennent s&#39;ajouter &#224; la liste. &lt;/span&gt;&lt;span class=&quot;UI&quot;&gt;&lt;br /&gt;&lt;br /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de lintrigue (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Intrigue/Art de l&#39;intrigue&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUI.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;Si le r&#244;deur choisit le style de combat &lt;b&gt;&lt;i&gt;astucieux&lt;/i&gt;&lt;/b&gt;, il peut choisir un des dons suivants chaque fois qu&#39;il gagne un don de style de combat, et s&#39;il choisit Expertise du combat, il compte comme ayant une valeur d&#39;Intelligence de 13 afin de choisir des dons qui ont Expertise du combat comme condition : &lt;a class=&quot;pagelink&quot; href=&quot;Esquive.html&quot; title=&quot;Esquive&quot;&gt;Esquive&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Expertise-Du-Combat.html&quot; title=&quot;Expertise du combat&quot;&gt;Expertise du combat&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-De-La-Subtilisation.html&quot; title=&quot;Science de la subtilisation&quot;&gt;Science de la subtilisation&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Science-Du-Sale-Coup.html&quot; title=&quot;Science du sale coup&quot;&gt;Science du sale coup&lt;/a&gt;. Au niveau 6, les dons &lt;a class=&quot;pagelink&quot; href=&quot;Sale-Coup-Sup&#233;rieur.html&quot; title=&quot;Sale coup sup&#233;rieur&quot;&gt;Sale coup sup&#233;rieur&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Subtilisation-Sup&#233;rieure.html&quot; title=&quot;Subtilisation sup&#233;rieure&quot;&gt;Subtilisation sup&#233;rieure&lt;/a&gt; s&#39;ajoutent &#224; la liste. Au niveau 10, les dons &lt;a class=&quot;pagelink&quot; href=&quot;Sale-Coup-Rapide.html&quot; title=&quot;Sale coup rapide&quot;&gt;Sale coup rapide&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Subtilisation-Rapide.html&quot; title=&quot;Subtilisation rapide&quot;&gt;Subtilisation rapide&lt;/a&gt; s&#39;ajoutent &#224; la liste.&lt;/span&gt;&lt;span class=&quot;APG&quot;&gt;&lt;br /&gt;&lt;br /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - R&#232;gles avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Player&#39;s Guide/Manuel des joueurs - R&#232;gles avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAPG.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;Si le r&#244;deur choisit le style de combat &lt;b&gt;&lt;i&gt;combat mont&#233;&lt;/i&gt;&lt;/b&gt;, il peut choisir un des dons suivants chaque fois qu’il gagne un don de style de combat : &lt;a class=&quot;pagelink&quot; href=&quot;Astuce-D&#233;quitation.html&quot; title=&quot;Astuce d&amp;#39;&#233;quitation&quot;&gt;Astuce d’&#233;quitation&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Attaque-Au-Galop.html&quot; title=&quot;Attaque au galop&quot;&gt;Attaque au galop&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Combat-Mont&#233;.html&quot; title=&quot;Combat mont&#233;&quot;&gt;Combat mont&#233;&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Tir-Mont&#233;.html&quot; title=&quot;Tir mont&#233;&quot;&gt;Tir mont&#233;&lt;/a&gt;. Au niveau 6, les dons &lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-Pour-La-Monture.html&quot; title=&quot;Bouclier pour la monture&quot;&gt;Bouclier pour la monture&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Charge-D&#233;vastatrice.html&quot; title=&quot;Charge d&#233;vastatrice&quot;&gt;Charge d&#233;vastatrice&lt;/a&gt; s&#39;ajoutent &#224; la liste. Au niveau 10, les dons &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;sar&#231;onner.html&quot; title=&quot;D&#233;sar&#231;onner&quot;&gt;D&#233;sar&#231;onner&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Tirailleur-Mont&#233;.html&quot; title=&quot;Tirailleur mont&#233;&quot;&gt;Tirailleur mont&#233;&lt;/a&gt; viennent s&#39;ajouter &#224; la liste.&lt;/span&gt;&lt;span class=&quot;UI&quot;&gt;&lt;br /&gt;&lt;br /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de lintrigue (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Intrigue/Art de l&#39;intrigue&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUI.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;Si le r&#244;deur choisit le style de combat &lt;b&gt;&lt;i&gt;mena&#231;ant&lt;/i&gt;&lt;/b&gt;, il peut choisir un des dons suivants chaque fois qu&#39;il gagne un don de style de combat : &lt;a class=&quot;pagelink&quot; href=&quot;Coup-Final-Sanglant.html&quot; title=&quot;Coup final sanglant&quot;&gt;Coup final sanglant&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;monstration.html&quot; title=&quot;D&#233;monstration&quot;&gt;D&#233;monstration&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Force-Intimidante.html&quot; title=&quot;Force intimidante&quot;&gt;Force intimidante&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Homme-De-Main.html&quot; title=&quot;Homme de main&quot;&gt;Homme de main&lt;/a&gt;. Au niveau 6, les dons &lt;a class=&quot;pagelink&quot; href=&quot;Briser-Les-D&#233;fenses.html&quot; title=&quot;Briser les d&#233;fenses&quot;&gt;Briser les d&#233;fenses&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Domination-Martiale.html&quot; title=&quot;Domination martiale&quot;&gt;Domination martiale&lt;/a&gt; s&#39;ajoutent &#224; la liste. Au niveau 10, les dons &lt;a class=&quot;pagelink&quot; href=&quot;Carnage-Effroyable.html&quot; title=&quot;Carnage effroyable&quot;&gt;Carnage effroyable&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Science-Du-Critique.html&quot; title=&quot;Science du critique&quot;&gt;Science du critique&lt;/a&gt; s&#39;ajoutent &#224; la liste.&lt;/span&gt;&lt;span class=&quot;UI&quot;&gt;&lt;br /&gt;&lt;br /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de lintrigue (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Intrigue/Art de l&#39;intrigue&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUI.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;Si le r&#244;deur choisit le style de combat &lt;b&gt;&lt;i&gt;trompeur&lt;/i&gt;&lt;/b&gt;, il peut choisir un des dons suivants chaque fois qu&#39;il gagne un don de style de combat : &lt;a class=&quot;pagelink&quot; href=&quot;Feinte-&#192;-Distance.html&quot; title=&quot;Feinte &#224; distance&quot;&gt;Feinte &#224; distance&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Feinte-De-D&#233;gagement.html&quot; title=&quot;Feinte de d&#233;gagement&quot;&gt;Feinte de d&#233;gagement&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-De-La-Feinte.html&quot; title=&quot;Science de la feinte&quot;&gt;Science de la feinte&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Feinte-&#192;-Deux-Armes.html&quot; title=&quot;Feinte &#224; deux armes&quot;&gt;Feinte &#224; deux armes&lt;/a&gt;. Au niveau 6, les dons &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tournement-Tactique.html&quot; title=&quot;D&#233;tournement tactique&quot;&gt;D&#233;tournement tactique&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Feinte-Sup&#233;rieure.html&quot; title=&quot;Feinte sup&#233;rieure&quot;&gt;Feinte sup&#233;rieure&lt;/a&gt; s&#39;ajoutent &#224; la liste. Au niveau 10, les dons &lt;a class=&quot;pagelink&quot; href=&quot;Coup-De-D&#233;gagement.html&quot; title=&quot;Coup de d&#233;gagement&quot;&gt;Coup de d&#233;gagement&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Tour-De-Passe-Passe.html&quot; title=&quot;Tour de passe-passe&quot;&gt;Tour de passe-passe&lt;/a&gt; s&#39;ajoutent &#224; la liste.&lt;/span&gt;&lt;br /&gt;&lt;br /&gt;Le r&#244;deur ne b&#233;n&#233;ficie de ses dons de style de combat que s’il porte une armure l&#233;g&#232;re, une armure interm&#233;diaire ou s’il ne porte aucune armure. Il perd leurs avantages s’il porte une armure lourde. Une fois qu’un r&#244;deur a opt&#233; pour un style de combat, ce choix ne peut plus &#234;tre modifi&#233;.&lt;br /&gt;&lt;br /&gt;
